        messages: transcript,
        provider: settings.provider,
        fetch: (url, init) => $.http.fetch(url, init),
        sleep: (ms, options) => $.clock.sleep(ms, options),
        timeoutMs: settings.compactTimeoutMs,
        minReduction: settings.compactMinReduction,
      });
