// Vendored from fast-jev-compaction (https://github.com/tamaratran/fast-jev-compaction)
// commit e3f262a7f4d4, MIT licensed; see LICENSE-fast-jev-compaction. Imports
// renamed to .ts. Changed on top of the vendored source: `concurrentMap`
// (below) was added, and `compact()`'s batch `Promise.all` replaced by it, to
// cap batch concurrency; `compact()` takes an optional `signal` to stop
// starting batches. Everything else in this file is unchanged.

import { noulAnswer } from "./request.ts";
import { collectToolCalls, estimateTokens, fitState } from "./state.ts";
import type {
  CallAnswer,
  CallDecision,
  CompactOptions,
  CompactResult,
  CompactionState,
  JevAsker,
  JevQuestions,
  Message,
  ResolvedCompactOptions,
  ToolCall,
  ToolUse,
} from "./types.ts";

export const DEFAULT_OPTIONS: ResolvedCompactOptions = {
  goal: '',
  keepThreshold: 0.5,
  preserveRecentMessages: 6,
  maxStateTokens: 25_000,
  maxRequestTokens: 30_000,
  truncateHeadChars: 300,
};

/** Tokens the request envelope (`model`, key names) adds around state and questions. */
const REQUEST_OVERHEAD_TOKENS = 20;

function finite(value: number | undefined, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

export function resolveOptions(options: CompactOptions = {}): ResolvedCompactOptions {
  return {
    goal: options.goal ?? DEFAULT_OPTIONS.goal,
    keepThreshold: finite(options.keepThreshold, DEFAULT_OPTIONS.keepThreshold),
    preserveRecentMessages: Math.max(
      0,
      Math.floor(
        finite(options.preserveRecentMessages, DEFAULT_OPTIONS.preserveRecentMessages),
      ),
    ),
    maxStateTokens: Math.max(1, finite(options.maxStateTokens, DEFAULT_OPTIONS.maxStateTokens)),
    maxRequestTokens: Math.max(
      1,
      finite(options.maxRequestTokens, DEFAULT_OPTIONS.maxRequestTokens),
    ),
    truncateHeadChars: Math.max(
      0,
      Math.floor(finite(options.truncateHeadChars, DEFAULT_OPTIONS.truncateHeadChars)),
    ),
    ...(options.textOf ? { textOf: options.textOf } : {}),
  };
}

/** The two `noul` questions asked about one call: keep the call, keep its result. */
export function questionsFor(call: ToolCall): JevQuestions {
  return {
    [`call_${call.id}`]: {
      type: 'noul',
      instructions: `Tool call ${call.id} (${call.tool}) should stay in the history: knowing this call was made, with its input, still matters for what the assistant does next`,
    },
    [`result_${call.id}`]: {
      type: 'noul',
      instructions: `The full output of tool call ${call.id} (${call.tool}, ${call.resultChars} chars) should stay in the history verbatim: the assistant still needs its contents and re-running the tool would not do`,
    },
  };
}

/**
 * Splits the candidate calls into batches whose questions, together with the
 * (always complete) state, fit one request.
 */
export function batchCalls(
  calls: readonly ToolCall[],
  stateTokens: number,
  options: Pick<ResolvedCompactOptions, 'maxRequestTokens'>,
): ToolCall[][] {
  const budget = options.maxRequestTokens - stateTokens - REQUEST_OVERHEAD_TOKENS;
  const batches: ToolCall[][] = [];
  let current: ToolCall[] = [];
  let currentTokens = 0;
  for (const call of calls) {
    const tokens = estimateTokens(JSON.stringify(questionsFor(call)));
    if (current.length > 0 && currentTokens + tokens > budget) {
      batches.push(current);
      current = [];
      currentTokens = 0;
    }
    if (current.length === 0 && tokens > budget) {
      throw new Error(
        `state leaves no room for questions (~${stateTokens} of ${options.maxRequestTokens} tokens)`,
      );
    }
    current.push(call);
    currentTokens += tokens;
  }
  if (current.length > 0) batches.push(current);
  return batches;
}

export function decideCall(
  call: Pick<ToolCall, 'id' | 'tool' | 'pinned'>,
  answer: CallAnswer,
  options: Pick<ResolvedCompactOptions, 'keepThreshold'>,
): CallDecision {
  const base = { id: call.id, tool: call.tool, ...answer };
  if (call.pinned) return { ...base, action: 'keep', reason: 'pinned' };
  if (answer.keepResult >= options.keepThreshold) {
    return { ...base, action: 'keep', reason: 'kept' };
  }
  if (answer.keepCall >= options.keepThreshold) {
    return { ...base, action: 'drop_result', reason: 'result_dropped' };
  }
  return { ...base, action: 'drop_call', reason: 'call_dropped' };
}

async function askBatch(
  asker: JevAsker,
  state: CompactionState,
  batch: readonly ToolCall[],
): Promise<Map<string, CallAnswer>> {
  const questions: JevQuestions = Object.assign({}, ...batch.map(questionsFor));
  const { answers } = await asker.ask(state, questions);
  return new Map(
    batch.map((call) => [
      call.id,
      {
        keepCall: noulAnswer(answers, `call_${call.id}`),
        keepResult: noulAnswer(answers, `result_${call.id}`),
      },
    ]),
  );
}

/**
 * Runs `fn` over `items` with at most `concurrency` in flight at once, in
 * item order (results are collected by index, not completion order, so
 * this is a true `map`, not a fire-and-forget pool). Useful for controlling
 * resource use when scoring large transcript fragments in many batches.
 *
 * If `signal` aborts, no new work starts and the promise rejects straight
 * away, with calls already started left to settle on their own. None of
 * them becomes an unhandled rejection, since each already has handlers
 * attached; calls already sent to the network complete regardless, since aborting the
 * signal only cancels a fetch that itself honours it (see askJev's note —
 * the engine's own fetch today does not).
 */
async function concurrentMap<T, U>(
  items: readonly T[],
  fn: (item: T) => Promise<U>,
  concurrency: number = 2,
  signal?: AbortSignal,
): Promise<U[]> {
  if (signal?.aborted) throw new Error("aborted");
  const results: U[] = new Array(items.length);
  const active = new Set<Promise<void>>();
  let aborted = false;
  // Resolved (not rejected — nothing here should reach an unhandled state)
  // the moment `signal` aborts, so a wait for a free slot wakes up right
  // away instead of only noticing abort on its next loop iteration.
  let wakeAborted: () => void = () => {};
  const abortedWake = new Promise<void>((resolve) => { wakeAborted = resolve; });
  const onAbort = () => { aborted = true; wakeAborted(); };
  signal?.addEventListener("abort", onAbort);
  try {
    for (const [i, item] of items.entries()) {
      if (aborted) throw new Error("aborted");
      // `p` closes over itself so its own settlement removes itself from
      // `active` — adding the `.finally()` wrapper instead (a *different*
      // promise) while deleting the original left `active` growing forever,
      // so the concurrency cap silently stopped limiting after the first
      // batch settled (measured: 67 batches → 66 in flight at once).
      const p: Promise<void> = fn(item)
        .then((result) => {
          results[i] = result;
        })
        .finally(() => {
          active.delete(p);
        });
      active.add(p);
      if (active.size >= concurrency) await Promise.race([...active, abortedWake]);
    }
    await Promise.all(active);
  } finally {
    signal?.removeEventListener("abort", onAbort);
  }
  if (aborted) {
    // Let whatever is still in flight settle before returning, so none of
    // it becomes an unhandled rejection after this function has returned.
    await Promise.all(active).catch(() => undefined);
    throw new Error("aborted");
  }
  return results;
}

function truncatedResultText(text: string, isError: boolean, headChars: number): string {
  if (text.length <= headChars + 120) return text;
  const head = headChars > 0 ? `${text.slice(0, headChars)}\n` : '';
  return `${head}[fast-jev-compaction truncated ${text.length - headChars} chars of this tool result${
    isError ? ' (error)' : ''
  }; re-run the tool if needed]`;
}

/**
 * Rebuilds the conversation from the decisions. A dropped call disappears
 * together with its result; a dropped result keeps a bounded head and note.
 * Messages that lose all their content are removed; untouched messages are
 * returned as the same objects they came in as.
 */
export function applyDecisions(
  messages: readonly Message[],
  decisions: readonly CallDecision[],
  calls: readonly ToolCall[],
  headChars: number,
): Message[] {
  const byId = new Map(calls.map((call) => [call.id, call]));
  const actions = new Map<string, CallDecision['action']>();
  for (const decision of decisions) {
    const call = byId.get(decision.id);
    if (call && decision.action !== 'keep') actions.set(call.tool_use_id, decision.action);
  }
  const kept: Message[] = [];
  for (const message of messages) {
    const touched =
      message.toolUses.some((tool) => actions.has(tool.tool_use_id)) ||
      (message.toolResults ?? []).some((result) => actions.has(result.tool_use_id));
    if (!touched) {
      kept.push(message);
      continue;
    }
    const toolUses = message.toolUses
      .filter((tool) => actions.get(tool.tool_use_id) !== 'drop_call')
      .map((tool) => {
        if (actions.get(tool.tool_use_id) !== 'drop_result') return tool;
        const text = truncatedResultText(
          tool.text ?? '',
          tool.isError ?? false,
          headChars,
        );
        if ((tool.text ?? '') === text) return tool;
        const copy: ToolUse = {
          tool_use_id: tool.tool_use_id,
          tool: tool.tool,
          input: tool.input,
          text,
        };
        if (tool.isError) copy.isError = true;
        return copy;
      });
    const toolResults = (message.toolResults ?? [])
      .filter((result) => actions.get(result.tool_use_id) !== 'drop_call')
      .map((result) => {
        if (actions.get(result.tool_use_id) !== 'drop_result') return result;
        const text = truncatedResultText(result.text, result.isError ?? false, headChars);
        return text === result.text
          ? result
          : {
              tool_use_id: result.tool_use_id,
              text,
              isError: result.isError,
            };
      });
    if (
      !message.toolUses.some(
        (tool) => actions.get(tool.tool_use_id) === 'drop_call',
      ) &&
      !(message.toolResults ?? []).some(
        (result) => actions.get(result.tool_use_id) === 'drop_call',
      ) &&
      toolUses.every((tool, index) => tool === message.toolUses[index]) &&
      toolResults.every(
        (result, index) => result === message.toolResults?.[index],
      )
    ) {
      kept.push(message);
      continue;
    }
    if (message.text.trim().length === 0 && toolUses.length === 0 && toolResults.length === 0) {
      continue;
    }
    const rebuilt: Message = { role: message.role, text: message.text, toolUses };
    if (toolResults.length > 0) rebuilt.toolResults = toolResults;
    kept.push(rebuilt);
  }
  return kept;
}

/** Characters of text, tool input and tool output a message holds. */
export function messageChars(message: Message): number {
  let total = message.text.length;
  for (const tool of message.toolUses) {
    try {
      total += JSON.stringify(tool.input).length;
    } catch {
      total += 20;
    }
  }
  for (const result of message.toolResults ?? []) total += result.text.length;
  return total;
}

export function reductionRatio(result: Pick<CompactResult, 'stats'>): number {
  const { charsBefore, charsAfter } = result.stats;
  return charsBefore === 0 ? 0 : (charsBefore - charsAfter) / charsBefore;
}

function count(decisions: readonly CallDecision[], reason: CallDecision['reason']): number {
  return decisions.filter((decision) => decision.reason === reason).length;
}

/**
 * Compacts a transcript by asking Jev, for every tool call outside the pinned
 * first and newest messages, whether the call and whether its result must
 * stay. The whole history (results omitted, fitted into `maxStateTokens`) is
 * sent as state with every batch of questions. Throws when Jev fails or the
 * history cannot be fitted; the caller decides whether to fall back.
 */
export async function compact(
  messages: readonly Message[],
  asker: JevAsker,
  options: CompactOptions = {},
  signal?: AbortSignal,
): Promise<CompactResult> {
  const started = Date.now();
  const resolved = resolveOptions(options);
  const calls = collectToolCalls(messages, resolved.preserveRecentMessages);
  const candidates = calls.filter((call) => !call.pinned);
  const charsBefore = messages.reduce((sum, message) => sum + messageChars(message), 0);

  let fitted: { tokens: number; stage: string } = { tokens: 0, stage: '' };
  let batches: ToolCall[][] = [];
  const answers = new Map<string, CallAnswer>();
  if (candidates.length > 0) {
    const state = fitState(messages, calls, resolved);
    fitted = state;
    batches = batchCalls(candidates, state.tokens, resolved);
    // Limit batch concurrency to 2 to avoid overwhelming the provider or local
    // resources when scoring large transcripts. The caller's signal (its own
    // timeout, enforced outside this function) stops any further batches from
    // being launched once it fires; batches already in flight are cancelled at
    // the network level only where the asker's own fetch honours the signal
    // baked into it (see askerOf in compactor.ts) — otherwise they still run
    // to completion and their answers are discarded.
    const answered = await concurrentMap(
      batches,
      (batch) => askBatch(asker, state.state, batch),
      2,
      signal,
    );
    for (const map of answered) for (const [id, answer] of map) answers.set(id, answer);
  }

  const decisions = calls.map((call) =>
    decideCall(call, answers.get(call.id) ?? { keepCall: 1, keepResult: 1 }, resolved),
  );
  const kept = applyDecisions(
    messages,
    decisions,
    calls,
    resolved.truncateHeadChars,
  );
  return {
    messages: kept,
    decisions,
    stats: {
      messagesBefore: messages.length,
      messagesAfter: kept.length,
      charsBefore,
      charsAfter: kept.reduce((sum, message) => sum + messageChars(message), 0),
      calls: calls.length,
      kept: count(decisions, 'kept'),
      resultsDropped: count(decisions, 'result_dropped'),
      callsDropped: count(decisions, 'call_dropped'),
      pinned: count(decisions, 'pinned'),
      stateTokens: fitted.tokens,
      stateStage: fitted.stage,
      requests: batches.length,
      ms: Date.now() - started,
    },
  };
}

files.hooks/status.ts:
/**
 * What `/jev` prints, the line at the top of a reply, and the summary under
 * it. `/jev` is the router's only guaranteed-visible surface: a command's
 * output row draws on every surface, where a footer label may not, so
 * anything you need to be sure of belongs here.
 *
 * Everything shown to the person is in short plain words: `kept fable:
 * haiku costs $4.41 vs $0.13`, not `held:haiku·$4.41>$0.125`.
 */

import type { JevResult } from "./jev.ts";
import {
  capTo,
  ceilingAt,
  confidenceShareOf,
  MODEL_OF,
  decisionOf,
  DEFAULT_STICKY_CONFIDENCE,
  effortNamed,
  EFFORTS,
  forcedDecision,
  holdsSonnetEffort,
  offeredTiers,
  stickyDecision,
  SUBAGENT_CONFIDENCE,
  subagentDecision,
  TIERS,
  UPGRADE_CONTEXT_TOKENS,
  upgradeBar,
  withCeiling,
  withinWindow,
  type Ceiling,
  type Decision,
  type Tier,
} from "./policy.ts";
import { sameModelAs,
  baseModel,
  breakEvenTokens,
  isDowngrade,
  PRICE,
  upgradeVerdict,
  priceOfModel,
  switchVerdict,
  usageCost,
  usd,
  fitsWindow,
  WINDOW_TOKENS,
  type Ttl,
} from "./pricing.ts";
import type { ProviderResult } from "./provider.ts";
import { compactionLine, type Compaction } from "./compactor.ts";

/**
 * What the API said a turn cost, and which model it says answered. The
 * shape of the engine's `TurnUsage`, spelled out here so this file stays
 * free of engine types and runs under plain `node`.
 */
export type Usage = {
  /** The model that answered, by the id the API reports. */
  model: string;
  input_tokens: number;
  output_tokens: number;
  cache_read_input_tokens: number;
  cache_creation_input_tokens: number;
};

/**
 * One turn's outcome, kept for the status report. `usage` arrives after the
 * decision, from the `stop` chunk of each step, so it is filled in later and
 * is absent for a turn still running or one whose response never came.
 */
export type Attempt = {
  prompt: string;
  ms: number;
  usage?: Usage;
  /** Dollars for `usage` at list price, or absent for a model without one. */
  cost?: number;
  /**
   * What started the turn, when it was not the person typing a task. Absent
   * for a typed prompt. `notify`: the main loop woke because a background
   * task finished, and the engine's `<task-notification>` was the turn's
   * text. `agent`: a subagent's own loop, which no `turn.start` announces;
   * its model was settled at `agent.spawn`, and its steps carry that. Without
   * this, one prompt that spawned three reviewers read as one reply that
   * changed model three times. `continue`: a bare go-ahead ("yes"), which
   * ran on the previous turn's decision without asking Jev. `nudge`: the
   * engine's own "say what you are doing, then continue", the same way, and
   * announced nowhere but here.
   */
  kind?: "notify" | "agent" | "continue" | "nudge";
  /**
   * Carried on from an earlier turn's decision without asking Jev: a
   * go-ahead, the engine's nudge, or a task's notification that continued
   * the reply's route. Its decision's confidence is that earlier turn's.
   */
  continued?: true;
  /** For `kind: 'agent'`: which subagent, as `$.agent.list()` describes it. */
  agent?: AgentTag;
} & ({ decision: Decision } | { skipped: string });

/**
 * Which subagent a turn ran in. `type` is the definition (`general-purpose`,
 * `Explore`); `label` its row's description (`Review library-sync cluster`),
 * or the id when the list has no row for it yet, in which case `type` is
 * absent too.
 */
export type AgentTag = {
  type?: string;
  label: string;
};

/** Percent, rounded, for a confidence. */
const pct = (n: number) => `${Math.round(n * 100)}%`;

/**
 * Why a turn did not run exactly as Jev asked, in plain words: held on its
 * previous tier for doubt or for price, held on its previous Sonnet effort,
 * forced to a tier the prompt named, capped at the ceiling, or sent the
 * effort a first request runs. Empty when it ran as asked.
 */
export function reasonsOf(attempt: Attempt): string[] {
  if (!("decision" in attempt)) return [];
  const d = attempt.decision;
  const out: string[] = [];
  if (d.held !== undefined) {
    // Same rung, different model: a session model off the ladder.
    const wanted =
      d.heldModel !== undefined && d.held === d.tier ? plain(d.heldModel) : d.held;
    const kept = d.held === d.tier ? plain(d.model) : d.tier;
    out.push(
      d.heldWindow !== undefined
        ? `kept ${kept}: too long for ${wanted} (${kOf(d.heldWindow)})`
        : d.heldCost !== undefined
          ? `kept ${kept}: ${wanted} costs ${usd(d.heldCost.go)} vs ${usd(d.heldCost.stay)}` +
            (d.heldCost.limit !== undefined
              ? `, over the ${usd(d.heldCost.limit)} limit`
              : "")
          : `kept ${kept}: Jev ${pct(d.confidence)} on ${wanted}` +
            (d.heldBar !== undefined ? `, needs ${pct(d.heldBar)}` : ""),
    );
  }
  // Kept, unless the tier it was on had outgrown its window: then the
  // step-up below says where it went.
  if (d.jevFailed !== undefined)
    out.push(d.outgrew !== undefined ? `Jev ${words(d.jevFailed)}` : `kept ${d.tier}: Jev ${words(d.jevFailed)}`);
  if (d.outgrew !== undefined)
    out.push(
      `${d.outgrew} too long, moved up only to ${d.tier}` +
        (d.wanted !== undefined && d.wanted !== d.tier ? ` (Jev wanted ${d.wanted})` : ""),
    );
  // Sonnet only: an effort change there re-caches half the prefix.
  if (d.heldEffort !== undefined) {
    out.push(
      `kept ${d.effort}: Jev ${pct(d.effortConfidence ?? 0)} on ${d.heldEffort}`,
    );
  }
  if (d.forced) out.push(pickOf(d));
  // The ceiling, and the engine running the capped effort higher on a
  // conversation's first request, read as one fact: what Jev wanted, what
  // the ceiling allowed, what actually ran. A first request that ran what
  // Jev wanted anyway was not capped in any way that matters.
  const capped = d.cappedEffort !== undefined && d.cappedEffort !== d.effort;
  if (capped && d.askedEffort !== undefined)
    out.push(
      `capped ${d.cappedEffort}→${d.askedEffort}; 1st request runs it as ${d.effort}`,
    );
  else if (capped) out.push(`capped from ${d.cappedEffort}`);
  else if (d.askedEffort !== undefined)
    out.push(`1st request runs ${d.askedEffort} as ${d.effort}`);
  return out;
}

/**
 * The cheapest tier above `from`, up to `to`, that takes `contextTokens`:
 * where a turn goes when what it would run on is too small. `strictlyAbove`
 * false lets `from` itself count. Null when none fits.
 */
function stepUp(
  from: Tier,
  to: Tier,
  offered: readonly Tier[],
  contextTokens: number,
  strictlyAbove = true,
): Tier | null {
  const lo = TIERS.indexOf(from);
  const hi = TIERS.indexOf(to);
  return (
    TIERS.find(
      (t, i) =>
        (strictlyAbove ? i > lo : i >= lo) &&
        i <= hi &&
        offered.includes(t) &&
        fitsWindow(t, contextTokens),
    ) ?? null
  );
}

/**
 * How a named tier reads: `your pick` when the turn runs on it, `you picked
 * haiku` when it did not fit and the turn ran elsewhere (kept on the running
 * tier, or stepped up), so the tier shown is never called the person's pick
 * when it was not.
 */
function pickOf(d: Decision): string {
  const named = d.held ?? d.wanted ?? d.outgrew ?? d.tier;
  return named === d.tier ? "your pick" : `you picked ${named}`;
}

/** The tier a step-up says was too long: the running one if it was, else Jev's pick. */
function outgrownOf(running: Decision | null, decision: Decision, contextTokens: number): Tier {
  return running !== null && !fitsWindow(running.tier, contextTokens) ? running.tier : decision.tier;
}

/**
 * A name from outside the plugin (an agent's type, a model id) as plain
 * words for the route line, the summary's fence and `/jev`: no backticks or
 * newlines to close the fence or start a heading, and not too long.
 */
export function plain(text: string): string {
  // Only what can close the fence or open a tag: inside a fence and on one
  // line, `#`, `|`, `_` and `[1m]` are plain text and stay.
  const flat = oneLine(String(text).replace(/\t/g, " ")).replace(/[`<>]/g, "");
  return flat.length > 60 ? `${flat.slice(0, 59)}…` : flat;
}

/** What started a turn nobody typed, in plain words; null for a typed prompt. */
export function originOf(
  attempt: Pick<Attempt, "kind" | "agent">,
): string | null {
  if (attempt.kind === "notify") return "task finished";
  if (attempt.kind === "continue") return "continuing";
  if (attempt.kind === "nudge") return "continuing";
  if (attempt.kind === "agent")
    return attempt.agent?.type ? `${plain(attempt.agent.type)} agent` : "agent";
  return null;
}

/**
 * A turn that is a task's notification: it opens with the envelope, an
 * element after the tag (prose that opens with the tag is a prompt).
 */
const NOTIFICATION = { test: (text: string) => opensWithEnvelope(text) };
/**
 * A tag's text, found by hand: the lazy pattern it replaces rescanned to the
 * end from every opening tag, quadratic on a run of openings with no close.
 */
const tagOf = (text: string, tag: string): string | undefined => {
  const open = text.indexOf(`<${tag}>`);
  if (open === -1) return undefined;
  const from = open + tag.length + 2;
  const close = text.indexOf(`</${tag}>`, from);
  return close === -1 ? undefined : text.slice(from, close).trim();
};

/**
 * Reads the engine's task notification, when the turn's text is one: what
 * the row should say instead of the XML envelope.
 */
export function notificationOf(text: string): string | null {
  if (!NOTIFICATION.test(text)) return null;
  // Read before the result, as what Jev is sent is: a result can quote a
  // summary or a task id of its own.
  const head = text.split(/<result\b/i)[0]!;
  return plain(tagOf(head, "summary") ?? `task ${tagOf(head, "task-id") ?? "?"}`);
}

/**
 * What Jev is told about a notification turn: the task's one-line summary,
 * and any text typed before the envelope, never the task's result, which
 * can quote whatever the agent read.
 */
export function notificationStateOf(text: string): string {
  // Only what cannot be a result: the text before the notification, and
  // its summary, read before its result starts. Nothing after the result's
  // opening is sent: a result can quote a whole envelope,
  // `</task-notification>` and all (an agent reading this very code), so
  // nothing after it can be told from the result. A turn that is a
  // notification is cut at its opening tag, whatever shape the rest has.
  const at = NOTIFICATION.test(text) ? text.search(/<task-notification\b/i) : envelopeAt(text);
  if (at === -1) return text.trim();
  const before = text.slice(0, at).trim();
  const head = text.slice(at).split(/<result\b/i)[0]!;
  const summary = plain(tagOf(head, "summary") ?? `task ${tagOf(head, "task-id") ?? "?"}`);
  return [before, summary].filter((p) => p !== "").join("\n");
}

/**
 * A notification's envelope, not a mention of the tag: an element follows
 * the opening tag (the engine's fields, in any order, or a comment).
 */
const TAG = "<task-notification";

/**
 * Whether an envelope opens at `at`: the tag (attributes of any length, on
 * one line), then an element or a comment. By hand, with the next `>` and
 * newline found once and reused: a pattern either rescanned a long line
 * of unclosed openings from each one, or, bounded, missed a tag with long
 * attributes and let its result through.
 */
function envelopeOpensAt(
  text: string,
  at: number,
  next: { gt: number; nl: number; seen?: number; ok?: boolean },
): boolean {
  const after = text.charCodeAt(at + TAG.length);
  if (after === after && /\w/.test(String.fromCharCode(after))) return false;
  if (next.gt !== -1 && next.gt < at) next.gt = text.indexOf(">", at);
  if (next.nl !== -1 && next.nl < at) next.nl = text.indexOf("\n", at);
  if (next.gt === -1 || (next.nl !== -1 && next.nl < next.gt)) return false;
  // Openings that share a `>` share what follows it: read once.
  if (next.seen === next.gt) return next.ok!;
  next.seen = next.gt;
  next.ok = elementAfter(text, next.gt + 1);
  return next.ok;
}

/** Whether an element or a comment opens at `i`, after blank space. */
function elementAfter(text: string, i: number): boolean {
  while (i < text.length && /\s/.test(text[i]!)) i++;
  if (text[i] !== "<") return false;
  if (text.startsWith("!--", i + 1)) return true;
  let j = i + 1;
  if (!/[a-z]/i.test(text[j] ?? "")) return false;
  while (j < text.length && /[\w-]/.test(text[j]!)) j++;
  return j < text.length && /[\s/>]/.test(text[j]!);
}

/** Where the first envelope in `text` opens, or -1. Linear. */
function firstEnvelope(text: string): number {
  // Found in `text` itself: lowercasing it first can change its length
  // ("İ" becomes two characters) and so every position after it. ASCII
  // case only, as the pattern's `i` without `u` folds (no Kelvin sign).
  const next = { gt: text.indexOf(">"), nl: text.indexOf("\n") };
  for (const m of text.matchAll(/<task-notification/gi)) if (envelopeOpensAt(text, m.index!, next)) return m.index!;
  return -1;
}

/** Whether `text` opens (after blank space) with an envelope. */
function opensWithEnvelope(text: string): boolean {
  const at = text.search(/\S/);
  if (at === -1 || !/^<task-notification/i.test(text.slice(at, at + TAG.length))) return false;
  return envelopeOpensAt(text, at, { gt: text.indexOf(">", at), nl: text.indexOf("\n", at) });
}

/**
 * Where a notification starts in text the person typed, or -1: the first
 * envelope, wherever it is and whatever quotes it. Nothing after it is
 * trusted, since a task's result can quote anything — fences, closing
 * tags, pastes — and whatever follows the envelope (a trailer, queued
 * prompts) cannot be told from the result. Decided for privacy over
 * routing: a prompt that quotes an example envelope has what follows the
 * quote left out of what Jev grades (the model still gets all of it).
 */
function envelopeAt(text: string): number {
  return firstEnvelope(text);
}

/** Whether `text` carries a task's notification anywhere, typed text before it or not. */
export function hasNotification(text: string): boolean {
  return envelopeAt(text) !== -1;
}

/** The task a notification is about: the agent's id, as `$.agent.list()` names it. */
export function notificationTaskOf(text: string): string | null {
  if (!NOTIFICATION.test(text)) return null;
  return tagOf(text.split(/<result\b/i)[0]!, "task-id") ?? null;
}

/**
 * Folds one step's usage into its turn: counts sum, the model is the last
 * step's, as the engine defines a turn's usage, and the dollars are re-priced
 * from the sum. Mutates, because the same object sits in the history and in
 * the by-turn lookup. Returns this one step's own cost (0 when it cannot be
 * priced), for the caller's running session total — which must count every
 * step's real cost regardless of whether the *row's* total stays presentable
 * (see below).
 *
 * `attempt.cost` is the row's own field, for display, and is deliberately
 * `undefined` — not "however much we could price" — the moment any one of
 * the turn's steps cannot be priced (a synthetic or unknown model): a partial
 * dollar figure with a $ sign in front of it reads as the whole turn's cost,
 * which it is not. That is a display choice; it must not double as the
 * accounting for money actually spent. An earlier version conflated the two
 * by having the caller diff `attempt.cost` before and after this call: the
 * moment `attempt.cost` was cleared (this step or an earlier one lacked a
 * price), the diff went negative and silently subtracted a step already
 * billed, or if the *first* step was unpriced, `attempt.cost` stayed
 * `undefined` forever and every later step's real cost added `0 - 0` —
 * missing the whole turn from the session total.
 */
export function addUsage(
  attempt: Attempt,
  usage: Usage,
  ttl: Ttl = "1h",
): number {
  const prior = attempt.usage;
  attempt.usage = {
    model: usage.model,
    input_tokens: (prior?.input_tokens ?? 0) + usage.input_tokens,
    output_tokens: (prior?.output_tokens ?? 0) + usage.output_tokens,
    cache_read_input_tokens:
      (prior?.cache_read_input_tokens ?? 0) + usage.cache_read_input_tokens,
    cache_creation_input_tokens:
      (prior?.cache_creation_input_tokens ?? 0) +
      usage.cache_creation_input_tokens,
  };
  // Each step at the model that answered it: a turn whose steps ran on
  // different models (a fallback) is not priced wholly at the last one's.
  const step = usageCost(usage.model, usage, ttl);
  if (step === null || (prior !== undefined && attempt.cost === undefined))
    delete attempt.cost;
  else attempt.cost = (attempt.cost ?? 0) + step;
  return step ?? 0;
}

/**
 * How much of what the turn's requests carried was read from cache, 0 to 1.
 * Everything carried is uncached input plus cache reads plus cache writes;
 * this is the cost-relevant measure, since reads bill at a tenth.
 */
export function cacheRatio(usage: Usage): number {
  const carried = carriedOf(usage);
  return carried === 0 ? 0 : usage.cache_read_input_tokens / carried;
}

/** What the last turn carried into the model: the context size, in tokens. */
export function carriedOf(usage: Usage): number {
  return (
    usage.input_tokens +
    usage.cache_read_input_tokens +
    usage.cache_creation_input_tokens
  );
}

/** No usage count past this: ten times the largest window. */
const MAX_COUNT = 10_000_000;

/**
 * A usage record with every count a number. The API omits the cache fields
 * on some paths; summed unchecked they made NaN of the turn's cost, the
 * session's `spent` and the context every price hold reads.
 */
export function normalUsage(usage: {
  model?: unknown;
  input_tokens?: unknown;
  output_tokens?: unknown;
  cache_read_input_tokens?: unknown;
  cache_creation_input_tokens?: unknown;
}): Usage {
  // A count the API could never mean (negative, NaN) is none: a negative
  // one would make a cost negative and the snapshot unloadable.
  // One larger than any window could carry is capped, so a cost or a
  // snapshot cannot overflow to Infinity (saved as null, the snapshot lost).
  const n = (v: unknown) =>
    typeof v === "number" && Number.isFinite(v) && v > 0 ? Math.min(v, MAX_COUNT) : 0;
  return {
    model: typeof usage.model === "string" ? usage.model : "",
    input_tokens: n(usage.input_tokens),
    output_tokens: n(usage.output_tokens),
    cache_read_input_tokens: n(usage.cache_read_input_tokens),
    cache_creation_input_tokens: n(usage.cache_creation_input_tokens),
  };
}

/**
 * How much of a prompt is kept in the history. Only its opening is shown,
 * and a session of long pastes kept whole outran the store's size cap, so
 * nothing saved.
 */
export const PROMPT_KEPT = 400;
export const kept = (text: string) => {
  // Kept in the history and the store: a task's result, typed ahead of or
  // not, is no more kept than it is sent to Jev.
  const own = NOTIFICATION.test(text) || hasNotification(text) ? notificationStateOf(text) : text;
  return own.length > PROMPT_KEPT ? own.slice(0, PROMPT_KEPT) : own;
};

export type Status = {
  enabled: boolean;
  /** The resumed session's cache expired and nothing has written it since. */
  cold?: boolean;
  surface: string | null;
  provider: ProviderResult;
  timeoutMs: number;
  /** The confidence a switch must clear, or null when stickiness is off. */
  sticky: number | null;
  /** The most an upgrade may cost over staying, or null for no limit. */
  upgradeMax?: number | null;
  /** The price checks: on, off, or absent on older callers. */
  price?: boolean;
  /** The most effort each tier may be asked for. */
  ceiling: Ceiling;
  /** Compaction by Jev: on, and the last one; absent on older callers. */
  compactOn?: boolean;
  compaction?: Compaction | null;
  /** Which prompt cache the session writes; the price of a switch depends on it. */
  ttl: Ttl;
  /** The context size the next turn would carry, or null before the first reply. */
  contextTokens: number | null;
  /** The main loop's model as `/model` shows it, or null when unknown. */
  sessionModel: string | null;
  /** What the main loop is running on, as the router last saw it; null when nothing yet. */
  running: Decision | null;
  offered: readonly Tier[];
  excluded: readonly Tier[];
  announce: boolean;
  attempts: readonly Attempt[];
  /** Dollars across every turn the router saw this session, at list price. */
  spent: number;
};

/**
 * What a switch is priced against: the context the turn carries, the output
 * it is likely to produce (the last turn's, or a typical one), and which
 * cache the session writes.
 */
type Economics = {
  contextTokens: number;
  outputTokens: number;
  ttl: Ttl;
  /** The running model's cache has expired (a resume after the TTL): staying is a write too. */
  cold?: boolean;
};

/**
 * What settles a main-loop turn beyond Jev's answer. `sticky` is the bar a
 * switch must clear, or null when switches are free; `running` what the last
 * routed turn ran on; `forced` a tier the prompt itself named, which takes
 * the tier question away from Jev and from stickiness both; `ceiling` the
 * most effort each tier may be asked for; `economics` what a downgrade is
 * priced against, absent when nothing is known about the context yet.
 */
type Hold = {
  sticky: number | null;
  running: Decision | null;
  forced?: Tier | null;
  ceiling?: Ceiling;
  economics?: Economics;
  /** The most an upgrade may cost over staying; null or absent for no limit. */
  upgradeMax?: number | null;
  /** The downgrade and upgrade price checks; absent reads as off. */
  price?: boolean;
};

/** A typical turn's output when the session has not produced one yet. */
export const TYPICAL_OUTPUT_TOKENS = 1500;

/**
 * One turn's outcome from Jev's answer, so the three ways a turn can fail to
 * route all land in one place and all get announced the same way.
 *
 * This is the only place a main-loop decision is settled: the route the
 * engine applies and the line /jev shows are the same object, so the two
 * cannot disagree. The order is the policy: a named tier first (it needs no
 * answer from Jev at all — effort defaults to medium), then stickiness on
 * the tier (Jev's doubt, or the price of a downgrade), then, for a turn that
 * stays on Sonnet, stickiness on the effort, then the tier's ceiling.
 */
export function attemptOf(
  text: string,
  result: JevResult,
  offered: readonly Tier[],
  hold: Hold = { sticky: null, running: null },
): Attempt {
  const summary = notificationOf(text);
  const head =
    summary === null
      ? { prompt: kept(text) }
      : { prompt: kept(summary), kind: "notify" as const };
  const forced = hold.forced ?? null;
  // A tier `/jev tiers off` dropped since it started running must not be
  // actively chosen or held to any more — but simply erasing `hold.running`
  // here for every such case went too far: it also disabled the window
  // guard's step-up (nothing to step *from*, so a turn too long for Jev's
  // pick fell to fully unrouted instead of the next tier up) and, for a
  // `running` that is only a placeholder seeded from the session model (no
  // key, nothing ever routed there), stripped the price check's own real
  // pricing data for no reason — an unrouted turn runs on that same
  // placeholder anyway, so refusing to weigh it costs money without
  // stopping anything. `withinWindow` and `stickyDecision` below are given
  // `offered` instead, and refuse to *land on or stay on* an excluded tier
  // at their own single decision points, while `hold.running` stays intact
  // everywhere else — including as the signal that there is something to
  // step up from, and as the real cache a switch away is priced against.

  if (!result.ok && forced === null) {
    // No answer from Jev: stay on the tier already running rather than drop
    // to the session model, which could be a cold cache and a switch back
    // afterwards. With nothing running, or nothing that fits, the turn is
    // left to the session model as before.
    // Only a tier Jev actually routed: a placeholder seeded from the
    // session model (no key, nothing routed yet) is the session model.
    if (hold.running !== null && hold.running.effortConfidence !== undefined) {
      const stay = continuationOf(
        text,
        hold.running,
        hold.ceiling ?? ceilingAt("max"),
        hold.economics?.contextTokens ?? null,
        offered,
      );
      if ("decision" in stay)
        return {
          ...head,
          ms: result.ms,
          decision: { ...stay.decision, confidence: 0, jevFailed: result.reason },
        };
    }
    return { ...head, ms: result.ms, skipped: result.reason };
  }

  const fresh = result.ok ? decisionOf(result.answers, offered) : null;
  let decision = forced !== null ? forcedDecision(forced, fresh) : fresh;
  if (!decision) {
    return {
      ...head,
      ms: result.ms,
      skipped: "Jev answered but named no tier we offered",
    };
  }
  // First of all, can the tier take a prompt this long? Haiku's window is
  // 200k; a turn carrying more is refused by the API, forced or not.
  if (hold.economics !== undefined) {
    const fits = withinWindow(
      decision,
      hold.running,
      hold.economics.contextTokens,
      offered,
    );
    if (fits === null) {
      // Neither Jev's pick nor what is running takes a context this long
      // (haiku past its window, Jev saying haiku again). Rather than leave
      // the turn to whatever the session model is, go up only as far as the
      // context needs.
      // With nothing known to be running, the session model holds the warm
      // cache, and staying there is cheaper than a cold write anywhere.
      const step =
        hold.running === null
          ? null
          : stepUp(decision.tier, TIERS.at(-1)!, offered, hold.economics.contextTokens);
      if (step === null) {
        return {
          ...head,
          ms: result.ms,
          skipped:
            `too long for ${decision.tier} (${kOf(hold.economics.contextTokens)})`,
        };
      }
      return {
        ...head,
        ms: result.ms,
        decision: capTo(
          {
            tier: step,
            model: MODEL_OF[step],
            effort: decision.effort,
            confidence: decision.confidence,
            ...(decision.effortConfidence !== undefined
              ? { effortConfidence: decision.effortConfidence }
              : {}),
            ...(decision.probabilities !== undefined
              ? { probabilities: decision.probabilities }
              : {}),
            // What was too long: the running tier when it was (a running
            // tier that fits but was turned off was not outgrown), else
            // Jev's pick.
            outgrew: outgrownOf(hold.running, decision, hold.economics.contextTokens),
            ...(decision.tier !== outgrownOf(hold.running, decision, hold.economics.contextTokens)
              ? { wanted: decision.tier }
              : {}),
            ...(decision.forced ? { forced: true as const } : {}),
          },
          hold.ceiling ?? ceilingAt("max"),
        ),
      };
    }
    if (fits.heldWindow !== undefined) {
      // Held on the running tier: on Sonnet an effort change still rewrites
      // much of the cache, so the effort gate applies here as well.
      const held =
        !fits.forced &&
        hold.sticky !== null &&
        hold.running !== null &&
        hold.running.effortConfidence !== undefined &&
        holdsSonnetEffort(fits, hold.running, hold.sticky, hold.ceiling ?? undefined)
          ? { ...fits, effort: hold.running.effort, heldEffort: fits.effort }
          : fits;
      return {
        ...head,
        ms: result.ms,
        decision: capTo(held, hold.ceiling ?? ceilingAt("max")),
      };
    }
  }
  // What Jev (or the prompt) picked, before any hold: what a hold that does
  // not fit gives way to.
  const picked: Decision | null = decision;
  const priced = hold.price === true;
  if ((hold.sticky !== null || priced) && !decision.forced) {
    const running = hold.running;
    const downgrade =
      running !== null && isDowngrade(running.tier, decision.tier);
    // The same rung on a different model — a session on `claude-opus-5`
    // that Jev keeps on opus — is a switch to a cold cache too, and priced
    // like a downgrade; there is no doubt to weigh, Jev agreed on the tier.
    const lateral =
      running !== null &&
      running.tier === decision.tier &&
      running.model !== decision.model;
    const fromPrice =
      running !== null ? (priceOfModel(running.model) ?? PRICE[running.tier]) : null;
    const upgrade =
      running !== null && !downgrade && !lateral && running.tier !== decision.tier;
    const verdict =
      !priced || running === null || fromPrice === null || hold.economics === undefined
        ? null
        : downgrade || lateral
          ? switchVerdict(
              running.tier,
              decision.tier,
              hold.economics.contextTokens,
              hold.economics.outputTokens,
              hold.economics.ttl,
              fromPrice,
              hold.economics.cold === true,
            )
          : upgrade && hold.upgradeMax != null
            ? upgradeVerdict(
                running.tier,
                decision.tier,
                hold.economics.contextTokens,
                hold.economics.outputTokens,
                hold.upgradeMax,
                hold.economics.ttl,
                fromPrice,
                hold.economics.cold === true,
              )
            : null;
    // An upgrade writes the whole context to the dearer tier; past 100k it
    // has to be surer than the bar.
    // Sticky off: no confidence bar, the price checks stand on their own.
    const bar =
      lateral || hold.sticky === null
        ? 0
        : !downgrade && hold.economics !== undefined
          ? upgradeBar(hold.sticky, hold.economics.contextTokens)
          : hold.sticky;
    decision = stickyDecision(decision, running, bar, verdict, offered);
  }
  // A forced turn named its tier and runs at medium (Jev is not asked).
  // The Sonnet effort gate does not get a vote here.
  if (
    !decision.forced &&
    hold.sticky !== null &&
    hold.running !== null &&
    // A placeholder for what a session runs on carries no effort Jev
    // chose; there is nothing to hold to.
    hold.running.effortConfidence !== undefined &&
    holdsSonnetEffort(decision, hold.running, hold.sticky, hold.ceiling ?? undefined)
  ) {
    decision = {
      ...decision,
      effort: hold.running.effort,
      heldEffort: decision.effort,
    };
  }
  // A hold must fit too: holding to haiku at 190k would send the turn where
  // the API refuses it. Jev's pick passed the check above, so the hold gives
  // way to it.
  if (
    hold.economics !== undefined &&
    decision.held !== undefined &&
    !fitsWindow(decision.tier, hold.economics.contextTokens) &&
    picked !== null
  ) {
    // The tier the hold kept is outgrown, but what held the move (doubt,
    // or an upgrade over the limit) still stands: go up only as far as the
    // context needs, the cheapest tier that fits, not all the way to Jev's
    // pick. When that is Jev's pick, it runs as picked.
    const held = decision;
    const step = stepUp(held.tier, picked.tier, offered, hold.economics.contextTokens, true);
    if (step === null || step === picked.tier) {
      decision = picked;
    } else {
      // What held the move priced haiku against Jev's pick; neither figure
      // describes the step, so the line says what happened instead.
      const { heldCost: _c, heldBar: _b, heldWindow: _w, held: _h, heldModel: _m, ...rest } = held;
      void _c, _b, _w, _h, _m;
      decision = { ...rest, tier: step, model: MODEL_OF[step], outgrew: held.tier, wanted: picked.tier };
    }
  }
  decision = capTo(decision, hold.ceiling ?? ceilingAt("max"));
  return { ...head, ms: result.ms, decision };
}

/**
 * A bare go-ahead's outcome: the previous turn's decision, carried over as
 * is. `held` and the like are dropped, since they described that turn's
 * choice, not this one's; the `continue` tag says what happened here. The
 * ceiling is re-applied so a change mid-session still binds.
 */
export function continuationOf(
  text: string,
  running: Decision,
  ceiling: Ceiling = ceilingAt("max"),
  contextTokens: number | null = null,
  offered: readonly Tier[] = TIERS,
): Attempt {
  const { tier, model, effort, confidence, effortConfidence } = running;
  // A tier `/jev tiers off` dropped since it started running is nothing
  // safe to continue: same outcome as having nothing to continue at all
  // (unrouted, the session model answers) rather than a switch quietly
  // biased toward a tier the person just turned off.
  if (!offered.includes(tier)) return continuationSkipped(text);
  if (contextTokens !== null && !fitsWindow(tier, contextTokens)) {
    const step = stepUp(tier, TIERS.at(-1)!, offered, contextTokens);
    if (step === null)
      return {
        prompt: kept(text),
        ms: 0,
        kind: "continue",
        skipped: `too long for ${tier} (${kOf(contextTokens)})`,
      };
    return {
      prompt: kept(text),
      ms: 0,
      kind: "continue",
      continued: true,
      decision: capTo(
        { tier: step, model: MODEL_OF[step], effort, confidence, effortConfidence, outgrew: tier },
        ceiling,
      ),
    };
  }
  return {
    prompt: kept(text),
    ms: 0,
    kind: "continue",
    continued: true,
    decision: capTo(
      { tier, model, effort, confidence, effortConfidence },
      ceiling,
    ),
  };
}

/**
 * A bare go-ahead when there is nothing safe to continue (first turn, or the
 * previous turn was unrouted / routing was off). Jev must not be asked: it
 * grades these as trivial at ~1.00 and would clear any sticky bar. The turn
 * stays on the session model.
 */
export function continuationSkipped(text: string): Attempt {
  return {
    prompt: kept(text),
    ms: 0,
    kind: "continue",
    skipped: "nothing to continue",
  };
}

/**
 * A spawned subagent's outcome from Jev's answer to its task. No stickiness
 * and no forcing: a subagent starts with an empty conversation, so there is
 * no cache to hold to, and the tier named in the person's prompt was for the
 * main loop. What there is instead is a confidence floor (`SUBAGENT_CONFIDENCE`),
 * below which the spawn is left on the model it would have had anyway.
 */
export function spawnAttemptOf(
  description: string,
  result: JevResult,
  offered: readonly Tier[],
  agent: AgentTag,
  ceiling: Ceiling = ceilingAt("max"),
): Attempt {
  const head = { prompt: kept(description), kind: "agent" as const, agent };
  if (!result.ok) return { ...head, ms: result.ms, skipped: result.reason };
  const fresh = decisionOf(result.answers, offered);
  if (!fresh) {
    return {
      ...head,
      ms: result.ms,
      skipped: "Jev answered but named no tier we offered",
    };
  }
  const decision = subagentDecision(fresh);
  if (!decision) {
    return {
      ...head,
      ms: result.ms,
      skipped: `Jev ${pct(fresh.confidence)} on ${fresh.tier}, needs ${pct(SUBAGENT_CONFIDENCE)}`,
    };
  }
  return { ...head, ms: result.ms, decision: capTo(decision, ceiling) };
}

/** The last few turns, newest first, so the report stays one screen. */
export const HISTORY_LIMIT = 5;

function shorten(text: string, width = 44): string {
  // A prompt or an agent's description can carry a terminal's escape
  // sequences (a model wrote it): dropped, with every line break folded.
  const flat = text.replace(CONTROL, "").replace(/[\s\u0085\u2028\u2029]+/g, " ").trim();
  return flat.length > width ? `${flat.slice(0, width - 1)}…` : flat;
}

/**
 * `Jev 57%`: how sure Jev was of the tier. Empty when Jev was not asked this
 * turn: a named tier, a go-ahead, or the engine's nudge.
 */
function sureOf(d: Decision, kind?: Attempt["kind"], continued?: boolean): string {
  // A notification that carried the reply's route on was not asked about.
  if (continued) return "";
  if (kind === "continue" || kind === "nudge") return "";
  if (d.forced && d.confidence === 0) return "";
  if (d.jevFailed !== undefined) return "";
  return `Jev ${pct(d.confidence)}`;
}

/** `opus-5-5` for `claude-opus-5-5-20260901`: the id without its prefix and date. */
function shortModel(model: string): string {
  // A usage record without a model id must not throw inside turn.step.
  if (typeof model !== "string" || model === "") return "unknown model";
  return plain(model.replace(/^claude-/, "").replace(/-\d{8}$/, ""));
}

function attemptLine(attempt: Attempt): string {
  const when = `${String(attempt.ms).padStart(4)}ms`;
  const origin = originOf(attempt);
  const what = `${origin ? `[${origin}] ` : ""}${shorten(attempt.prompt)}`;
  if ("skipped" in attempt) {
    // A subagent's row names the agent first, then why: "under the bar"
    // and "Jev timed out" are different stories.
    return attempt.kind === "agent"
      ? `  ${when}  not routed — ${what} · ${words(attempt.skipped)}`
      : `  ${when}  not routed — ${words(attempt.skipped)}`;
  }
  const d = attempt.decision;
  // A held turn's reason carries the confidence; saying it twice is noise.
  const notes = [
    ...(d.held === undefined ? [sureOf(d, attempt.kind, attempt.continued)] : []),
    ...reasonsOf(attempt),
  ].filter((n) => n !== "");
  return `  ${when}  ${d.tier}·${d.effort}  ${notes.join("; ")}  ${what}`;
}

/** Thousands rounded down, for a limit that must not be overstated: 4.1k, 45k. */
function kOfDown(n: number): string {
  const k = n / 1000;
  return k < 10 ? `${Math.floor(k * 10) / 10}k` : `${Math.floor(k)}k`;
}

/** Thousands or millions, rounded, for token counts: 130k, 2k, 3.3M. */
function kOf(n: number): string {
  const k = Math.round(n / 1000);
  // 999,500 rounds to a thousand k, which is a million.
  if (k >= 1000) return `${(n / 1_000_000).toFixed(1)}M`;
  return `${k}k`;
}

/**
 * `fable-5-1 ✓`: the model the API says answered, and whether it is the one
 * the router asked for (a dated id still counts). A different model is the
 * one case worth looking at: `sonnet-5 ⚠ asked opus-5-5`.
 */
function answeredBy(attempt: Attempt): string {
  const usage = attempt.usage!;
  const got = shortModel(usage.model);
  if (!("decision" in attempt)) return got;
  const asked = attempt.decision.model;
  return sameModel(asked, usage.model)
    ? `${got} ✓`
    : `${got} ⚠ asked ${shortModel(asked)}`;
}

/**
 * Whether the model the API reports is the one asked for: the same id, give
 * or take the engine's `[1m]` and a trailing date. `claude-opus-5-5` does not
 * confirm `claude-opus-5`, although one begins with the other.
 */
function sameModel(asked: string, got: unknown): boolean {
  // `[1m]`, a date, and a provider's spelling (`…@date`, `us.anthropic.…`)
  // all answer for the model asked.
  return typeof got === "string" && sameModelAs(asked, got);
}

/** `$0.50 · 47k in (49% cached) · 0k out`. */
function costPhrase(usage: Usage, cost: number | undefined): string {
  const parts = [];
  if (cost !== undefined) parts.push(usd(cost));
  parts.push(
    `${kOf(carriedOf(usage))} in (${Math.round(cacheRatio(usage) * 100)}% cached)`,
    `${kOf(usage.output_tokens)} out`,
  );
  return parts.join(" · ");
}

/**
 * The line under a turn in /jev saying what the API reports actually
 * answered, and what the requests carried. This is the intrinsic check: the
 * route line is what we asked for; this is what we got.
 */
function usageLine(attempt: Attempt): string | null {
  if (!attempt.usage) return null;
  return `          → ${answeredBy(attempt)} · ${costPhrase(attempt.usage, attempt.cost)}`;
}

/**
 * The summary under a finished reply: one block for everything the reply
 * took, however many turns it spanned. A reply that spawns background work
 * is several turns — the one you typed, then one per task that finished and
 * woke the loop — and a block under each read as one reply changing model
 * three times. So the turns are gathered and written once, at the end.
 *
 * Two lines as a rule: what answered and what it cost, then why it did not
 * run as Jev asked, when it did not.
 *
 *   fable-5-1 ✓ xhigh · Jev 97% · $0.14 · 130k in (91% cached) · 2k out
 *   kept fable: haiku costs $4.41 vs $0.13
 *
 * Fenced, because markdown collapses leading whitespace and joins
 * consecutive lines into one paragraph: unfenced, the rows would render as
 * a single run-on.
 */
export function replySummary(turns: readonly Attempt[]): string | null {
  const main = turns.filter((t) => t.kind !== "agent");
  const agents = turns.filter((t) => t.kind === "agent");
  const priced = turns.filter((t) => t.usage !== undefined);
  if (main.length === 0 || priced.length === 0) return null;

  const rows: string[] = [];
  const head: string[] = [];

  // What answered.
  if (main.length === 1) {
    const only = main[0]!;
    if ("decision" in only) {
      const d = only.decision;
      head.push(
        `${only.usage ? answeredBy(only) : shortModel(d.model)} ${d.effort}`,
      );
      // How the tier was settled, always in this spot: Jev's confidence, the
      // prompt's own pick, or a go-ahead carrying the last one on.
      // A held turn's confidence is in the tier it did not move to; the
      // note under this line says so, so none is shown here.
      const how = d.forced
        ? pickOf(d)
        : only.kind === "continue" || only.kind === "nudge"
          ? "continuing"
          : d.held !== undefined
            ? ""
            : sureOf(d, only.kind, only.continued);
      if (how !== "") head.push(how);
    } else {
      head.push(only.usage ? answeredBy(only) : "session model");
      head.push(`not routed: ${words(only.skipped)}`);
    }
  } else {
    // A tier the person named is marked, as the single-turn line says "your pick".
    const legs = main.map((t) =>
      "decision" in t
        ? `${t.decision.tier}${t.decision.forced ? ` (${pickOf(t.decision)})` : ""}${t.usage && !answeredBy(t).endsWith("✓") ? " ⚠" : ""}`
        : "session",
    );
    const woken = main.filter((t) => t.kind === "notify").length;
    const nudged = main.filter((t) => t.kind === "nudge").length;
    const because = [
      ...(woken > 0 ? [`${woken} woken by tasks`] : []),
      ...(nudged > 0 ? [`${nudged} nudged`] : []),
    ];
    head.push(
      `${main.length} turns: ${legs.join(", ")}` +
        (because.length > 0 ? ` (${because.join(", ")})` : ""),
    );
  }

  // The whole reply's cost.
  const sum = priced.reduce(
    (acc, t) => {
      const u = t.usage!;
      acc.input += u.input_tokens;
      acc.read += u.cache_read_input_tokens;
      acc.write += u.cache_creation_input_tokens;
      acc.output += u.output_tokens;
      if (t.cost !== undefined) acc.cost += t.cost;
      else acc.unpriced = true;
      return acc;
    },
    { input: 0, read: 0, write: 0, output: 0, cost: 0, unpriced: false },
  );
  const carried = sum.input + sum.read + sum.write;
  const cached = carried === 0 ? 0 : Math.round((100 * sum.read) / carried);
  if (!sum.unpriced) head.push(usd(sum.cost));
  head.push(`${kOf(carried)} in (${cached}% cached)`, `${kOf(sum.output)} out`);
  rows.push(head.join(" · "));

  // What its agents ran on and cost.
  if (agents.length > 0) {
    const legs = agents.map((a) => {
      const name = plain(a.agent?.type ?? "agent");
      // What ran it: the model the API reported, else the tier routed to.
      const on = a.usage
        ? shortModel(a.usage.model)
        : "decision" in a
          ? a.decision.tier
          : "its own model";
      return `${name} ${on}${a.cost !== undefined ? ` ${usd(a.cost)}` : ""}`;
    });
    rows.push(`agents: ${legs.join(", ")}`);
  }

  // Why a turn did not run exactly as Jev asked.
  // (How the tier was settled is on the first line already; a multi-turn
  // reply counts its wake-ups and nudges there.)
  main.forEach((t, i) => {
    const why = reasonsOf(t).filter((r) => !r.startsWith("your pick") && !r.startsWith("you picked"));
    if (why.length === 0) return;
    rows.push(`${main.length > 1 ? `turn ${i + 1}: ` : ""}${why.join("; ")}`);
  });

  return ["```", ...rows, "```"].join("\n");
}

/** `medium for all`, or `medium (opus: xhigh, fable: xhigh)`. */
export function ceilingLine(ceiling: Ceiling): string {
  const counts = new Map<string, number>();
  for (const tier of TIERS)
    counts.set(ceiling[tier], (counts.get(ceiling[tier]) ?? 0) + 1);
  let common = ceiling.haiku;
  for (const tier of TIERS) {
    const effort = ceiling[tier];
    if ((counts.get(effort) ?? 0) > (counts.get(common) ?? 0)) common = effort;
  }
  const rest = TIERS.filter((t) => ceiling[t] !== common).map(
    (t) => `${t}: ${ceiling[t]}`,
  );
  return rest.length === 0
    ? `${common} for all`
    : `${common} (${rest.join(", ")})`;
}

/**
 * The report, as plain lines. Written so the first three tell you whether
 * the thing is on at all, which is the question that brings people here.
 */
export function statusReport(status: Status): string {
  // The engine prefixes the plugin's name; a header here said it twice.
  const lines: string[] = [""];

  lines.push(`  routing   ${status.enabled ? "on" : "off (/jev on)"}`);
  lines.push(`  surface   ${status.surface === null ? "unknown" : plain(status.surface)}`);

  if (status.provider.ok) {
    const key =
      status.provider.name === "typesafe"
        ? "TYPESAFE_API_KEY"
        : "AI_GATEWAY_API_KEY";
    lines.push(
      `  provider  ${status.provider.name} · ${key} is set · ${plain(status.provider.model)}`,
    );
  } else {
    // The reason names the fix: a missing key, a bad base URL, a provider
    // forced without its key. "No keys" alone sent people after the wrong one.
    lines.push(`  provider  NOT SET UP — ${words(status.provider.reason)}; nothing will route`);
  }

  lines.push(`  budget    ${status.timeoutMs}ms`);
  lines.push(
    `  sticky    ${
      status.sticky === null
        ? "off (/jev sticky on)"
        : `on, switch needs ${pct(status.sticky)} ` +
          `(${pct(upgradeBar(status.sticky, UPGRADE_CONTEXT_TOKENS))} up past ` +
          `${kOf(UPGRADE_CONTEXT_TOKENS)})`
    }`,
  );
  if (status.price !== undefined)
    lines.push(
      `  price     ${
        status.price
          ? "on, a downgrade has to pay" +
            (status.upgradeMax === 0
              ? ", an upgrade may not cost more than staying"
              : status.upgradeMax != null
                ? `, an upgrade may cost ${usd(status.upgradeMax)} over staying`
                : "")
          : "off (/jev price on)"
      }`,
    );
  lines.push(`  ceiling   ${ceilingLine(status.ceiling)}`);
  if (status.compactOn !== undefined)
    lines.push(
      `  compact   ${
        status.compactOn
          ? `${
              status.provider.ok && status.provider.name !== "typesafe"
                ? "on, but the gateway cannot score tool calls (needs TypeSafe direct): the engine summarises"
                : "on, Jev prunes tool calls"
            }${status.compaction ? ` · last: ${compactionLine(status.compaction)}` : ""}`
          : "off (/jev compact on)"
      }`,
    );
  lines.push(`  session   ${sessionLine(status)}`);
  lines.push(`  cache     ${cacheLine(status)}`);
  lines.push(`  tiers     ${status.offered.join(", ")}`);
  lines.push(
    `  announce  ${status.announce ? "on, a line per turn" : "off (/jev loud)"}`,
  );
  // Derived from `offered`, not the raw `excluded` field: `offeredTiers`
  // falls back to the full ladder when every tier is named excluded (an
  // env-misconfigured JEV_ROUTER_EXCLUDE, say), and the raw field would
  // then say every tier is both offered (line above) and excluded — the
  // `tiers` line above is already correct either way, and this one must
  // agree with it rather than with what was merely asked for.
  const notOffered = TIERS.filter((t) => !status.offered.includes(t));
  if (notOffered.length > 0) {
    lines.push(`  excluded  ${notOffered.join(", ")}`);
  }
  if (status.spent > 0) lines.push(`  spent     ${usd(status.spent)} this session`);

  lines.push("");
  if (status.attempts.length === 0) {
    lines.push("  No turns yet. Send a prompt, then run /jev again.");
    return lines.join("\n");
  }

  lines.push("  Recent turns, newest first:");
  for (const attempt of status.attempts) {
    lines.push(attemptLine(attempt));
    const usage = usageLine(attempt);
    if (usage !== null) lines.push(usage);
  }

  return lines.join("\n");
}

/** `claude-opus-5, running on fable` — the session's model and what is warm. */
function sessionLine(status: Status): string {
  const model = status.sessionModel === null ? "unknown" : plain(status.sessionModel);
  if (status.running === null) return `${model}, nothing routed yet`;
  // `[1m]` and a date are spellings of the same model; compared whole, not
  // as shown (a long Bedrock or Vertex id is cut for the line).
  return status.sessionModel !== null && sameModelAs(status.running.model, status.sessionModel)
    ? `${model}, still on it`
    : `${model}, running on ${status.running.tier}`;
}

/**
 * `1h writes · 201k context · fable→haiku pays below 3k`: which cache the
 * session writes, what the next turn carries, and where the cheapest
 * downgrade from the running tier stops paying, so a hold is predictable.
 */
function cacheLine(status: Status): string {
  const parts = [`${status.ttl} writes`];
  if (status.contextTokens === null) return `${parts[0]} · no context yet`;
  parts.push(`${kOf(status.contextTokens)} context`);
  const running = status.running;
  if (running !== null) {
    const from = running.tier;
    // A tier turned off is not a downgrade the router can make.
    const to = TIERS.find((t) => status.offered.includes(t) && isDowngrade(from, t));
    if (to !== undefined) {
      // The main loop's own output: a subagent's is its own conversation.
      const last = status.attempts.find((a) => "decision" in a && a.usage && a.kind !== "agent");
      const out = Math.min(
        last?.usage?.output_tokens ?? TYPICAL_OUTPUT_TOKENS,
        TYPICAL_OUTPUT_TOKENS,
      );
      // Cold as the switch is priced: a resumed cache that expired costs a
      // write to stay on as well.
      const be = breakEvenTokens(
        from,
        to,
        out,
        status.ttl,
        priceOfModel(running.model) ?? PRICE[from],
        status.cold === true,
      );
      // Never a figure above the real one: under 1k it is shown whole.
      parts.push(
        be === 0
          ? `${from}→${to} never pays`
          : `${from}→${to} pays below ${be < 1000 ? `${be}` : kOfDown(be)}`,
      );
    }
  }
  return parts.join(" · ");
}

/** The reply to `/jev on`, `/jev off` and anything unrecognised. */
export function toggleReply(enabled: boolean): string {
  return enabled
    ? "Jev routing on. The next turn picks its own model."
    : "Jev routing off. Turns run on the session model.";
}

/**
 * The line put at the top of each reply, as markdown.
 *
 * Markdown, because the line rides in the reply's own text and that is what
 * the transcript renders. A blockquote sets it off from prose with a rail
 * and dimmer text. Neither a render hook nor `$.ui.log` drew anything in the
 * desktop app, so this is the styling that is actually available.
 *
 *   > ✳️ fable · xhigh · Jev 57% · 324ms
 *   > ✳️ fable · low · kept fable: haiku costs $1.02 vs $0.020 · 352ms
 *   > ⚠️ not routed: typesafe said HTTP 401
 */
export function liveLine(attempt: Attempt): string {
  // One line, always: a reason carrying a newline (an engine error, say)
  // would break the blockquote and no longer read as this line.
  if ("skipped" in attempt) {
    return `> ⚠️ not routed: ${words(attempt.skipped)}`;
  }
  const d = attempt.decision;
  const parts = [
    d.tier,
    d.effort,
    ...(d.held === undefined ? [sureOf(d, attempt.kind, attempt.continued)] : []),
    ...reasonsOf(attempt),
    ...(originOf(attempt) ? [originOf(attempt)!] : []),
    // A clock stepped back mid-call gives a negative span; it reads as 0.
    `${Math.max(0, Math.round(attempt.ms))}ms`,
  ].filter((p) => p !== "");
  return oneLine(`> ✳️ ${parts.join(" · ")}`);
}

/**
 * The rule drawn under the line, closing it off from the reply.
 *
 * It needs the blank line before it: `---` on the line after text is a setext
 * heading underline, which would turn the route into a heading instead.
 */
export const REPLY_SEPARATOR = "\n\n---\n\n";

/**
 * What sits between the reply's last text and the summary. A blank line, so
 * the fence opens a block of its own instead of joining the last paragraph.
 */
export const FOOTER_SEPARATOR = "\n\n";

/**
 * A route line's own shape, as `liveLine` writes it: a tier, and the time
 * Jev took at the end; or the not-routed warning. Matching the shape, not
 * just the opening `> ⚠️ `, keeps a warning callout the model writes itself
 * ("> ⚠️ This force-pushes.") from being taken for a copied line.
 */
const ROUTE_LINE_BODY = `(?:✳️ (?:${TIERS.join("|")}) · [^\\n]*· \\d+(?:\\.\\d+)?ms|⚠️ not routed: [^\\n]*)`;
const ROUTE_LINE_SHAPE = new RegExp(`^> ${ROUTE_LINE_BODY}(?=\\n|$)`);

/** Whether text opens with a route line of the plugin's own shape. */
export function isRouteLine(text: string): boolean {
  return ROUTE_LINE_SHAPE.test(text);
}

/** A route line the model wrote itself at the start of its text, with the rule under it. */
const IMITATED_LINE = new RegExp(`^> ${ROUTE_LINE_BODY}(?:\\n+---(?:\\n+|$)|\\n+|$)`);

/**
 * `text` without a summary it ends in, and the blank lines before it. The
 * newlines are dropped by hand: a leading `\n*` in the pattern made a text
 * ending in many blank lines quadratic (100k of them took eight seconds).
 */
function withoutSummary(text: string): string {
  const at = summaryAt(text);
  if (at === -1) return text;
  let end = at;
  while (end > 0 && text[end - 1] === "\n") end--;
  return text.slice(0, end);
}

/**
 * Where a summary the model wrote itself at the end of its text opens, or
 * -1: a closing fence at the very end, after a newline; the fence before it
 * followed by a newline; no backtick between; a first line that reads
 * `(N% cached)`. By hand: the pattern this replaces rescanned a long
 * summary-shaped line from every position, quadratic in the reply.
 */
function summaryAt(text: string): number {
  const e = text.trimEnd().length;
  if (!text.slice(0, e).endsWith("\n```")) return -1;
  const close = e - 3;
  const open = text.lastIndexOf("```", close - 1);
  if (open === -1) return -1;
  const body = text.slice(open + 3, close);
  if (!body.startsWith("\n") || body.includes("`")) return -1;
  const eol = body.indexOf("\n", 1);
  return /\(\d+% cached\)/.test(body.slice(1, eol)) ? open : -1;
}

/** One line: newlines and the space around them become a single space. */
function oneLine(text: string): string {
  // Every line break a renderer honours, not only `\n`: a `\r` or U+2028
  // ends the route line early as surely. Other control characters (a
  // terminal's escape sequences) are dropped.
  const bare = text.replace(CONTROL, "");
  if (!LINE_BREAK.test(bare)) return bare;
  return bare
    .split(LINE_BREAK)
    .map((t) => t.trim())
    .filter((t) => t !== "")
    .join(" ");
}

/** What a renderer may take for a line break. */
const LINE_BREAK = /[\n\r\v\f\u0085\u2028\u2029]/;
/** Control characters that are not line breaks (tabs are spaces). */
// eslint-disable-next-line no-control-regex
const CONTROL = /[\x00-\x08\x0e-\x1f\x7f-\x84\x86-\x9f]/g;

/**
 * A reason from outside the plugin (an error's text, a provider's word) as
 * plain words for the route line, the summary and `/jev`: one line, with
 * nothing that closes a fence or opens a tag.
 */
export function words(text: string): string {
  const flat = oneLine(String(text).replace(/\t/g, " ")).replace(/[`<>]/g, "").replace(/ {2,}/g, " ");
  return flat.length > 160 ? `${flat.slice(0, 159)}…` : flat;
}

/**
 * The model's text without a route line or summary it wrote itself. Both
 * are in its past replies, so it copies them: seen 2026-09-23, a footer with
 * made-up figures ($0.21, 450k in) typed above the real one, which read as a
 * second copy of the plugin. Only the ends of the text are touched, so a
 * line or summary quoted in the middle of a reply stays.
 */
export function withoutImitations(text: string): string {
  return withoutSummary(text.replace(IMITATED_LINE, ""));
}

/** How a route line opens, for telling a partial one from ordinary text. */
const LINE_OPENERS = ["> ✳️ ", "> ⚠️ "];

/** Every way a route line's first words can read, once past its opener. */
const LINE_STARTS = ["> ⚠️ not routed: ", ...TIERS.map((t) => `> ✳️ ${t} · `)];

/** Whether a first line still being streamed could turn out to be a route line. */
function couldBeRouteLine(partial: string): boolean {
  const line = partial.slice(0, ROUTE_LINE_MAX + 1).split("\n", 1)[0]!;
  return LINE_STARTS.some((s) => s.startsWith(line) || line.startsWith(s));
}

/**
 * The rule under a route line, after the line's own newline: the canonical
 * form (a blank line before it, which is what this plugin itself writes —
 * REPLY_SEPARATOR) and the bare form `IMITATED_LINE` also strips (the rule
 * directly under the line, no blank line). Streamed a few characters at a
 * time, a copied line's rule can arrive as either shape; checking only the
 * canonical one against `rest` let a bare split ("> ✳️ … · 12ms\n", then
 * "-", then "--\n\n") desync from LINE_RULE at the very first "-" (it does
 * not start with "\n"), settle immediately, and leak the tail of the rule
 * ("---\n\n") through as ordinary text.
 */
const LINE_RULE = "\n---\n\n";
const LINE_RULE_BARE = "---\n\n";

/**
 * The most a summary the model copied can run to. The plugin's own is a
 * line a turn under a head line; past this a fence is the model's own code,
 * streamed rather than held, and left alone at the end.
 */
const SUMMARY_MAX = 16_000;

/**
 * The longest first line a route line can have. Past it the block's start
 * is ordinary text, streamed rather than held for a newline.
 */
const ROUTE_LINE_MAX = 1_000;

/** The longest first line a summary can have: all of one, at most. */
const SUMMARY_HEAD_MAX = SUMMARY_MAX;

/** Blank lines after a copied rule waited for, before the text after it streams. */
const RULE_TAIL_MAX = 1_024;

/** A summary's first line, once the fence has opened. */
const SUMMARY_HEAD = /^[^\n`]*\(\d+% cached\)/;

/**
 * `withoutImitations` for text that streams in pieces. The engine hands a
 * block's text over a few tokens at a time, so a copied line or summary is
 * spread across many chunks and no single one matches. This holds back only
 * what could still turn out to be one: the start of a block until its first
 * line is settled, and a fence until its first line shows whether it is a
 * summary (a summary fence is held to the end of the block). Everything else
 * passes straight through.
 *
 * Held text rides out on the latest held chunk, so the engine still gets a
 * chunk it streamed (with its `ref`) and the block's text stays whole.
 */
export class ImitationFilter<C extends { kind: "text"; index: number; text: string }> {
  private block = -1;
  private settled = false;
  private held = "";
  private carrier: C | null = null;
  /** How far past a copied route line's newline the held text is blank lines. */
  private blanksTo = 0;
  /**
   * `held` opens with a fence already found to be a summary's start, as long
   * as it was when checked: text added after it is checked on its own,
   * rather than the whole fence rescanned for every piece.
   */
  private pinned: { fence: number; length: number; close: number; open?: true } | null = null;

  /** A text piece in; the pieces to pass on now. */
  push(chunk: C): C[] {
    const out = chunk.index === this.block ? [] : this.end();
    if (chunk.index !== this.block) {
      this.block = chunk.index;
      this.settled = false;
      this.blanksTo = 0;
    }
    this.held += chunk.text;
    this.carrier = chunk;
    const now = this.release(false);
    if (now !== "") out.push({ ...chunk, text: now });
    if (this.held === "") this.carrier = null;
    return out;
  }

  /** The block is over (another block, a non-text chunk, the end): what is still held. */
  end(): C[] {
    if (this.carrier === null) return [];
    const text = this.release(true);
    const carrier = this.carrier;
    this.carrier = null;
    return text === "" ? [] : [{ ...carrier, text }];
  }

  /** Takes what can go out now off `held`; with `final`, all of it. */
  private release(final: boolean): string {
    if (!this.settled) {
      const h = this.held;
      const opener = LINE_OPENERS.find((o) => h.startsWith(o));
      if (opener === undefined || !couldBeRouteLine(h)) {
        // Still possibly the start of a line: wait for more.
        if (!final && LINE_OPENERS.some((o) => o.startsWith(h))) return "";
      } else {
        const eol = h.indexOf("\n");
        // Still waiting for the line to end, while it is short enough to be one.
        if (eol === -1 && !final && h.length <= ROUTE_LINE_MAX) return "";
        if (eol === -1 && !final) {
          // Too long to be a route line: ordinary text, streamed as it is.
          this.settled = true;
          return this.release(false);
        }
        if (eol !== -1) {
          // The rule under it may still be arriving, in either shape: any
          // number of blank lines, then a rule. The blank lines are counted
          // as they arrive, not rescanned for each piece.
          if (this.blanksTo < eol + 1) this.blanksTo = eol + 1;
          while (this.blanksTo < h.length && h[this.blanksTo] === "\n") this.blanksTo++;
          const tail = h.slice(this.blanksTo);
          // Waited through a screenful or so of them at most: holding a long
          // run costs a copy of it per piece, and a model does not copy one.
          if (
            !final &&
            this.blanksTo - eol <= RULE_TAIL_MAX &&
            tail.length <= RULE_TAIL_MAX &&
            /^(?:-{1,2}|---\n*)?$/.test(tail)
          )
            return "";
        }
        this.held = h.replace(IMITATED_LINE, "");
      }
      this.settled = true;
    }
    if (final) {
      const all = withoutSummary(this.held);
      this.held = "";
      this.pinned = null;
      return all;
    }
    if (this.stillPinned()) return "";
    this.pinned = null;
    const from = this.holdFrom(this.held);
    const now = this.held.slice(0, from);
    this.held = this.held.slice(from);
    // Held from a fence (after the blank lines held with it) whose first
    // line is in: pinned, so later pieces are checked on their own.
    const fence = from === 0 ? this.held.search(/[^\n]/) : -1;
    if (fence !== -1 && this.held.startsWith("```\n", fence)) {
      this.pinned =
        this.held.indexOf("\n", fence + 4) !== -1
          ? { fence, length: this.held.length, close: this.held.indexOf("\n```", fence + 4) }
          : // Its first line still arriving: held while it has no backtick.
            { fence, length: this.held.length, close: -1, open: true };
    }
    return now;
  }

  /**
   * Whether the pinned summary fence still holds with what was added since:
   * no longer than a summary, and nothing but blank space after its close.
   */
  private stillPinned(): boolean {
    const pin = this.pinned;
    if (pin === null || this.held.length - pin.fence - 3 > SUMMARY_MAX) return false;
    if (pin.open) {
      // A newline ends the first line: checked whole, once. A backtick in
      // it means no summary.
      const added = this.held.slice(pin.length);
      if (/[\n`]/.test(added)) return false;
      this.pinned = { ...pin, length: this.held.length };
      return true;
    }
    let close = pin.close;
    if (close === -1) close = this.held.indexOf("\n```", Math.max(pin.fence + 4, pin.length - 4));
    if (close !== -1 && /\S/.test(this.held.slice(Math.max(close + 4, pin.length)))) return false;
    this.pinned = { fence: pin.fence, length: this.held.length, close };
    return true;
  }

  /** Where text that could still be a summary starts; the length when none. */
  private holdFrom(text: string): number {
    for (let p = text.indexOf("```"); p !== -1; p = text.indexOf("```", p + 3)) {
      if (p > 0 && text[p - 1] !== "\n") continue;
      const after = text.slice(p + 3);
      if (!"\n".startsWith(after.slice(0, 1))) continue; // ```bash and the like
      // Too long for a summary: the model's own fence, and it streams.
      if (after.length > SUMMARY_MAX) continue;
      if (after === "") return this.backToBlankLines(text, p);
      const eol = after.indexOf("\n", 1);
      // A first line longer than any summary's is the model's own.
      if (eol === -1 ? after.length > SUMMARY_HEAD_MAX : eol > SUMMARY_HEAD_MAX) continue;
      const head = after.slice(1, eol === -1 ? undefined : eol);
      if (eol === -1 || SUMMARY_HEAD.test(head)) {
        if (eol === -1 && !/^[^\n`]*$/.test(head)) continue;
        // Closed, with text after it: quoted mid-reply, and it streams.
        const close = after.indexOf("\n```", eol);
        if (close !== -1 && /\S/.test(after.slice(close + 4))) continue;
        return this.backToBlankLines(text, p);
      }
    }
    // A fence may be starting at the very end.
    const tail = text.match(/(?:^|\n)`{1,2}$/);
    if (tail) return this.backToBlankLines(text, tail.index! + (tail[0].startsWith("\n") ? 1 : 0));
    // Trailing newlines wait for what follows: a fence after them would take
    // them with it.
    return this.backToBlankLines(text, text.length);
  }

  /**
   * Holds the blank lines before a fence with it, so none dangle if it goes:
   * up to a screenful, not an unbounded run, which would be rescanned on
   * every piece.
   */
  private backToBlankLines(text: string, p: number): number {
    for (let held = 0; p > 0 && text[p - 1] === "\n" && held < 64; held++) p--;
    return p;
  }
}

/**
 * The reply to a `/jev` argument nothing reads. A removed toggle
 * (`/jev xhigh on`) is pointed at the ceiling that replaced it.
 */
export function unknownCommandReply(arg: string, legacy: boolean): string {
  const usage =
    "/jev (status), on, off, quiet, loud, sticky [off|0.6], price [on|off], " +
    "compact [on|off], tiers [on|off <tier>], ceiling <effort> [tiers], " +
    "or an effort on its own (/jev xhigh fable).";
  return legacy
    ? `"/jev ${arg}" was one of the old effort toggles; the ceiling replaced them. ` +
        `Try /jev ceiling xhigh to allow up to xhigh, or /jev ceiling medium to cap there. ${usage}`
    : `"/jev ${arg}" is not a command. ${usage}`;
}

/** The reply to `/jev quiet` and `/jev loud`. */
export function announceReply(announce: boolean): string {
  return announce
    ? "Jev will announce each route in the transcript."
    : "Jev will route quietly. Run /jev to see what it has been doing.";
}

/**
 * Reads `/jev sticky`, `/jev sticky off`, `/jev sticky 0.6` and says what the
 * bar is now. `current` is the session's bar, or null when it is off.
 *
 * A bare `sticky` keeps a bar already set rather than resetting it to the
 * default, so turning it off and on again does not silently lose a tuned
 * value. A number that cannot be a confidence changes nothing and says so,
 * rather than falling back to the default: an unnoticed 0.75 is worse than a
 * refusal, since the point of the bar is knowing which one you are running.
 */
export function stickyCommand(
  rest: string,
  current: number | null,
): { sticky: number | null; text: string } {
  const arg = rest.trim().toLowerCase();

  // The words JEV_ROUTER_STICKY reads as off. `0` stays a bar out of range.
  if (arg === "off" || arg === "false" || arg === "no" || arg === "none") {
    return {
      sticky: null,
      text: "No confidence bar: switches follow Jev, subject to the price checks (/jev price). /jev sticky brings the bar back.",
    };
  }

  if (arg === "" || arg === "on") {
    const bar = current ?? DEFAULT_STICKY_CONFIDENCE;
    return { sticky: bar, text: stuckAt(bar) };
  }

  const ratio = confidenceShareOf(arg);
  if (ratio === null) {
    return {
      sticky: current,
      text:
        `"${rest.trim()}" is not a confidence. Give a number between 0 and 1 ` +
        "(0.6), or a percentage (60).",
    };
  }
  return { sticky: ratio, text: stuckAt(ratio) };
}

function stuckAt(bar: number): string {
  return (
    `Holding the tier until Jev is ${pct(bar)} sure of a switch, ` +
    "/jev sticky off removes the bar; the price checks are /jev price."
  );
}

/**
 * Reads `/jev tiers`, `/jev tiers off fable`, `/jev tiers on fable`. A bare
 * `tiers` reports which are offered; `off <tier>...` drops one or more from
 * the question Jev is asked, `on <tier>...` puts them back. At least one
 * tier is always named — `off` alone would either do nothing (there is
 * nothing to default to dropping) or, taken as "drop every tier", trip
 * `offeredTiers`'s own fallback to the full ladder and silently undo itself,
 * which would read as broken rather than as a no-op. The same reasoning
 * refuses turning off the one tier still on: that is what `/jev off` (no
 * tier name) is for, and letting it happen here would look identical to
 * having no effect while actually meaning something different underneath.
 */
export function tiersCommand(
  rest: string,
  current: readonly Tier[],
): { excluded: Tier[]; text: string } {
  // Commas and semicolons separate as spaces do, as JEV_ROUTER_EXCLUDE reads them.
  const parts = rest.trim().toLowerCase().split(/[\s,;]+/).filter(Boolean);
  if (parts.length === 0) {
    return { excluded: [...current], text: tiersReply(current) };
  }
  const [onOff, ...names] = parts;
  if (onOff !== "on" && onOff !== "off") {
    return {
      excluded: [...current],
      text: `"${onOff}" is not on or off. /jev tiers off fable drops a tier, /jev tiers on fable brings it back.`,
    };
  }
  if (names.length === 0) {
    return {
      excluded: [...current],
      text: `Name at least one tier: ${TIERS.join(", ")}. /jev tiers ${onOff} fable.`,
    };
  }
  const unknown = names.filter((n) => !(TIERS as string[]).includes(n));
  if (unknown.length > 0) {
    return {
      excluded: [...current],
      text:
        `"${unknown.join(", ")}" ${unknown.length === 1 ? "is" : "are"} not ` +
        `a tier. Use ${TIERS.join(", ")}.`,
    };
  }
  const dropped = new Set(current);
  for (const name of names as Tier[]) {
    if (onOff === "off") dropped.add(name);
    else dropped.delete(name);
  }
  if (onOff === "off" && dropped.size >= TIERS.length) {
    // The tier to spare is the last-named one that was actually on before
    // this command — not simply the last name given: a name already off
    // (redundant, or a duplicate) is not the one putting every tier out,
    // and "sparing" it would leave the real offender dropped and an
    // already-off tier back on, the opposite of what was asked and of what
    // the reply below says happened.
    const wasOn = names.filter((n) => !current.includes(n as Tier)) as Tier[];
    const kept = wasOn[wasOn.length - 1] ?? (names[names.length - 1] as Tier);
    dropped.delete(kept);
    return {
      excluded: TIERS.filter((t) => dropped.has(t)),
      text: `At least one tier has to stay on; left ${kept} alone. /jev off turns routing off entirely.`,
    };
  }
  const excluded = TIERS.filter((t) => dropped.has(t));
  return { excluded, text: tiersReply(excluded) };
}

function tiersReply(excluded: readonly Tier[]): string {
  // Through `offeredTiers`, not a plain "everything not in excluded": naming
  // every tier excluded (JEV_ROUTER_EXCLUDE misconfigured, say — the
  // command itself never lets this happen) falls back to the full ladder
  // rather than offering nothing, and the reply must describe what is
  // actually offered, not what was merely asked to be dropped.
  const on = offeredTiers(new Set(excluded));
  if (on.length === TIERS.length) {
    return `Every tier is offered to Jev: ${TIERS.join(", ")}. /jev tiers off fable drops one.`;
  }
  const off = TIERS.filter((t) => !on.includes(t));
  return (
    `${on.join(", ")} offered; ${off.join(", ")} off. ` +
    "/jev tiers on brings a dropped one back."
  );
}

/**
 * Reads `/jev ceiling`, `/jev ceiling xhigh`, `/jev ceiling xhigh fable opus`,
 * `/jev ceiling off`. A bare `ceiling` reports; an effort sets it on every
 * tier, or on the tiers named after it; `off` lifts every cap (which is max).
 * An unreadable effort or tier changes nothing and says so.
 */
export function ceilingCommand(
  rest: string,
  current: Ceiling,
): { ceiling: Ceiling; text: string } {
  // Commas and semicolons separate as spaces do, as JEV_ROUTER_EXCLUDE reads them.
  const parts = rest.trim().toLowerCase().split(/[\s,;]+/).filter(Boolean);
  if (parts.length === 0) {
    return { ceiling: current, text: ceilingReply(current) };
  }
  const effort = effortNamed(parts[0] ?? "");
  if (effort === null) {
    return {
      ceiling: current,
      text:
        `"${parts[0]}" is not an effort. Use ${EFFORTS.join(", ")} ` +
        "or off; /jev ceiling xhigh fable raises one tier.",
    };
  }
  const names = parts.slice(1);
  const unknown = names.filter((n) => !(TIERS as string[]).includes(n));
  if (unknown.length > 0) {
    return {
      ceiling: current,
      text:
        `"${unknown.join(", ")}" ${unknown.length === 1 ? "is" : "are"} not ` +
        `a tier. Use ${TIERS.join(", ")}.`,
    };
  }
  const next = withCeiling(
    current,
    effort,
    names.length === 0 ? TIERS : (names as Tier[]),
  );
  return { ceiling: next, text: ceilingReply(next) };
}

function ceilingReply(ceiling: Ceiling): string {
  return (
    `Effort ceiling: ${ceilingLine(ceiling)}. Jev's pick above it is capped ` +
    "and the line says what it wanted. /jev ceiling xhigh raises every " +
    "tier, /jev ceiling xhigh fable one, /jev ceiling off lifts them."
  );
}

